// Platform security: every secret carries the ACME_ prefix (scanner + Vault
// injector only handle that namespace). Auth.js reads its auth secret from a
// fixed set of *stock* env names with no prefix indirection:
//   AUTH_SECRET, AUTH_SECRET_1..3   (core: packages/core/src/lib/utils/env.ts)
//   NEXTAUTH_SECRET                 (next-auth: packages/next-auth/src/lib/env.ts)
// Our services pass it explicitly as `secret: process.env.ACME_AUTH_SECRET`,
// so re-adding a stock name silently re-wires resolution away from injection.
import { readFile } from "node:fs/promises"

const STOCK = /\bAUTH_SECRET/          // not ACME_AUTH_SECRET / NEXTAUTH_SECRET
// Upstream code and its tests/docs are the only places the stock name is legit.
const ALLOW = [
  /^packages\//, /^docs\//, /^turbo\.json$/,
  /(^|\/)(test|e2e)\//, /\.(test|spec)\./, /^apps\/examples\//,
]
const files = process.argv.slice(2)
let failed = false
for (const f of files) {
  if (ALLOW.some((re) => re.test(f))) continue
  const lines = (await readFile(f, "utf8")).split("\n")
  lines.forEach((line, i) => {
    if (STOCK.test(line)) {
      failed = true
      console.error(`${f}:${i + 1}: stock secret name — use ACME_AUTH_SECRET`)
    }
  })
}
process.exit(failed ? 1 : 0)
```

